import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Flow } from 'flow-sdk';
import { SectionLabel, PillButton, FieldDropdown, DragNumberField } from './components/Primitives';

interface CostumeItem {
  name: string;
  description: string;
  imageMediaId?: string;
  base64?: string;
}

export default function App() {
  const [sourceImage, setSourceImage] = useState<{ mediaId: string; base64: string; mimeType: string } | null>(null);
  const [items, setItems] = useState<CostumeItem[]>([]);
  const [status, setStatus] = useState<string>('Ready');
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [gridCols, setGridCols] = useState(4);
  const [gridRows, setGridRows] = useState(3);
  const [bgColor, setBgColor] = useState('#f5f5f5');
  const [exportState, setExportState] = useState<'idle' | 'saving'>('idle');

  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Global styles injection
  useEffect(() => {
    const id = 'fashion-grid-styles';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', sans-serif; overflow: hidden; }
      .dark-scrollbar::-webkit-scrollbar { width: 4px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 10px; }
      @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      .animate-spin-slow { animation: spin 3s linear infinite; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleSelectImage = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      setSourceImage({ mediaId: media.mediaId, base64: media.base64, mimeType: media.mimeType });
      setItems([]);
      setStatus('Image loaded');
    } catch (e) {
      console.error(e);
    }
  };

  const analyzeAndGenerate = async () => {
    if (!sourceImage) return;
    setIsProcessing(true);
    setProgress(0);
    setStatus('Analyzing costume components...');

    try {
      // 1. Analyze with Gemini
      const analysisPrompt = `Analyze this fashion photo and list all individual clothing items and accessories visible. 
      For each item, provide a clear 'name' and a highly descriptive 'description' suitable for a high-quality product image generator.
      Focus on flat lay style descriptions.
      Return the result as a raw JSON array of objects with 'name' and 'description' keys. Do not include markdown formatting.`;

      const { text } = await Flow.generate.text(analysisPrompt, {
        images: [{ base64: sourceImage.base64, mimeType: sourceImage.mimeType }],
        systemInstruction: "You are an expert fashion stylist and image prompting specialist."
      });

      // Clean up JSON if model adds markdown
      const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const detectedItems: CostumeItem[] = JSON.parse(jsonStr);
      setItems(detectedItems);

      // 2. Generate each item
      setStatus('Generating high-quality item cards...');
      const updatedItems = [...detectedItems];

      for (let i = 0; i < updatedItems.length; i++) {
        const item = updatedItems[i];
        setProgress(Math.round(((i + 1) / updatedItems.length) * 100));
        setStatus(`Generating ${item.name}...`);

        try {
          const result = await Flow.generate.image({
            prompt: `A professional studio product photograph of ${item.description}, flat lay style, isolated on a clean neutral studio background, 4k resolution, high contrast.`,
            modelDisplayName: '🍌 Nano Banana Pro',
            aspectRatio: '1:1'
          });

          updatedItems[i] = { ...item, base64: result.base64, imageMediaId: result.mediaId };
          setItems([...updatedItems]);
        } catch (genError) {
          console.error(`Failed to generate ${item.name}:`, genError);
        }
      }

      setStatus('Complete!');
    } catch (error) {
      console.error(error);
      setStatus('Error processing image');
    } finally {
      setIsProcessing(false);
      setProgress(100);
    }
  };

  const drawGrid = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Fixed 16:9 internal resolution
    const W = 1920;
    const H = 1080;
    canvas.width = W;
    canvas.height = H;

    // Background
    ctx.fillStyle = bgColor;
    ctx.fillRect(0, 0, W, H);

    // Grid Calculations
    const padding = 60;
    const gap = 30;
    const totalGapX = (gridCols - 1) * gap;
    const totalGapY = (gridRows - 1) * gap;
    const availableW = W - (padding * 2) - totalGapX;
    const availableH = H - (padding * 2) - totalGapY;
    const itemW = availableW / gridCols;
    const itemH = availableH / gridRows;

    // Render items
    items.forEach((item, index) => {
      if (index >= gridCols * gridRows) return;

      const col = index % gridCols;
      const row = Math.floor(index / gridCols);
      const x = padding + col * (itemW + gap);
      const y = padding + row * (itemH + gap);

      // Card Background
      ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
      ctx.shadowColor = 'rgba(0,0,0,0.1)';
      ctx.shadowBlur = 20;
      ctx.shadowOffsetY = 10;
      ctx.beginPath();
      ctx.roundRect(x, y, itemW, itemH, 20);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      if (item.base64) {
        const img = new Image();
        img.src = `data:image/png;base64,${item.base64}`;
        img.onload = () => {
          // Calculate object-fit contain
          const scale = Math.min(itemW / img.width, (itemH * 0.7) / img.height) * 0.8;
          const drawW = img.width * scale;
          const drawH = img.height * scale;
          const drawX = x + (itemW - drawW) / 2;
          const drawY = y + (itemH * 0.1);
          ctx.drawImage(img, drawX, drawY, drawW, drawH);

          // Label
          ctx.fillStyle = '#333';
          ctx.font = 'bold 24px Google Sans Text';
          ctx.textAlign = 'center';
          ctx.fillText(item.name.toUpperCase(), x + itemW / 2, y + itemH - 40);
        };
      } else {
        // Placeholder text if not generated yet
        ctx.fillStyle = '#999';
        ctx.font = 'italic 18px Google Sans Text';
        ctx.textAlign = 'center';
        ctx.fillText(item.name, x + itemW / 2, y + itemH / 2);
      }
    });

    // Handle Empty Slots (Visual Placeholder)
    const totalSlots = gridCols * gridRows;
    for (let i = items.length; i < totalSlots; i++) {
      const col = i % gridCols;
      const row = Math.floor(i / gridCols);
      const x = padding + col * (itemW + gap);
      const y = padding + row * (itemH + gap);

      ctx.setLineDash([10, 10]);
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.roundRect(x, y, itemW, itemH, 20);
      ctx.stroke();
      ctx.setLineDash([]);
    }
  }, [items, gridCols, gridRows, bgColor]);

  useEffect(() => {
    drawGrid();
  }, [drawGrid]);

  const handleDownload = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    setExportState('saving');
    try {
      const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
      await Flow.download({
        base64,
        mimeType: 'image/jpeg',
        filename: `costume_analysis_${Date.now()}.jpg`
      });
      setExportState('idle');
    } catch (e) {
      console.error(e);
      setExportState('idle');
    }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">
      {/* Left Panel */}
      <div className="w-[300px] h-full border-r border-white/15 flex flex-col justify-between py-3 px-[10px] shrink-0">
        <div className="flex flex-col gap-6 overflow-y-auto pr-1 dark-scrollbar">

          {/* Source Input */}
          <div className="flex flex-col gap-2">
            <SectionLabel>Costume Source</SectionLabel>
            <div 
              onClick={handleSelectImage}
              className="group relative w-full aspect-square rounded-xl border border-dashed border-[#595959] hover:border-white/40 transition-colors cursor-pointer flex flex-col items-center justify-center overflow-hidden bg-white/5"
            >
              {sourceImage ? (
                <>
                  <img src={`data:${sourceImage.mimeType};base64,${sourceImage.base64}`} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" />
                  <div className="absolute inset-0 flex items-center justify-center bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity">
                    <span className="material-symbols-outlined text-white">add_photo_alternate</span>
                  </div>
                </>
              ) : (
                <>
                  <span className="material-symbols-outlined text-[32px] text-white/40 group-hover:text-white/60 mb-2">add_photo_alternate</span>
                  <span className="text-[11px] text-white/40">Choose reference photo</span>
                </>
              )}
            </div>
            {sourceImage && (
              <PillButton variant="outline" icon={<span className="material-symbols-outlined text-[18px]">refresh</span>} onClick={handleSelectImage}>
                Change Image
              </PillButton>
            )}
          </div>

          {/* Configuration */}
          <div className="flex flex-col gap-2">
            <SectionLabel>Grid Layout</SectionLabel>
            <div className="flex gap-1">
              <DragNumberField label="Cols" value={gridCols} min={1} max={6} onChange={setGridCols} className="flex-1" />
              <DragNumberField label="Rows" value={gridRows} min={1} max={6} onChange={setGridRows} className="flex-1" />
            </div>
            <FieldDropdown 
              label="Background Theme" 
              value={bgColor === '#f5f5f5' ? 'Studio Light' : bgColor === '#1a1a1a' ? 'Deep Shadow' : 'Champagne'} 
              options={['Studio Light', 'Deep Shadow', 'Champagne']}
              onChange={(val) => {
                if (val === 'Studio Light') setBgColor('#f5f5f5');
                else if (val === 'Deep Shadow') setBgColor('#1a1a1a');
                else setBgColor('#f3e5f5');
              }}
            />
          </div>

          {/* Status / Items List */}
          {items.length > 0 && (
            <div className="flex flex-col gap-2">
              <SectionLabel>Detected Components ({items.length})</SectionLabel>
              <div className="flex flex-col gap-1 max-h-[200px] overflow-y-auto dark-scrollbar pr-1">
                {items.map((item, idx) => (
                  <div key={idx} className="flex items-center gap-2 p-2 rounded-lg bg-white/5 border border-white/10">
                    <div className="w-8 h-8 rounded bg-white/10 flex items-center justify-center overflow-hidden shrink-0">
                      {item.base64 ? (
                        <img src={`data:image/png;base64,${item.base64}`} className="w-full h-full object-cover" />
                      ) : (
                        <span className="material-symbols-outlined text-[14px] text-white/30">inventory_2</span>
                      )}
                    </div>
                    <span className="text-[10px] font-medium truncate">{item.name}</span>
                    {isProcessing && idx === items.findIndex(it => !it.base64) && (
                      <span className="material-symbols-outlined text-[12px] text-[#969696] animate-spin-slow ml-auto">progress_activity</span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Action Area */}
        <div className="flex flex-col gap-2 pt-4 border-t border-white/10">
          {isProcessing ? (
            <div className="flex flex-col gap-2">
              <div className="flex justify-between text-[11px] font-medium px-1">
                <span className="text-white/60">{status}</span>
                <span>{progress}%</span>
              </div>
              <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden">
                <div className="h-full bg-white transition-all duration-300" style={{ width: `${progress}%` }} />
              </div>
            </div>
          ) : (
            <>
              <PillButton 
                variant="solid" 
                icon={<span className="material-symbols-outlined text-[18px]">auto_awesome</span>}
                onClick={analyzeAndGenerate}
                disabled={!sourceImage}
              >
                Analyze Costume
              </PillButton>
              <PillButton 
                variant="outline" 
                icon={<span className="material-symbols-outlined text-[18px]">{exportState === 'saving' ? 'progress_activity' : 'download'}</span>}
                onClick={handleDownload}
                disabled={items.length === 0 || exportState === 'saving'}
              >
                {exportState === 'saving' ? 'Exporting...' : 'Export Grid (16:9)'}
              </PillButton>
            </>
          )}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col items-center justify-center p-8 bg-[#050505]">
        <div className="relative w-full max-w-[1200px] aspect-[16/9] bg-white/5 rounded-2xl overflow-hidden shadow-2xl border border-white/10 group">
          <canvas 
            ref={canvasRef} 
            className="w-full h-full object-contain"
          />

          {items.length === 0 && !isProcessing && (
            <div className="absolute inset-0 flex flex-col items-center justify-center text-white/20">
              <span className="material-symbols-outlined text-[64px] mb-4">grid_view</span>
              <p className="text-sm font-medium tracking-wide">YOUR COSTUME GRID WILL APPEAR HERE</p>
              <p className="text-[11px] mt-2 opacity-50 uppercase">Select an image and click "Analyze Costume" to begin</p>
            </div>
          )}

          {isProcessing && (
            <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex flex-col items-center justify-center">
              <div className="w-12 h-12 border-2 border-white/20 border-t-white rounded-full animate-spin-slow mb-4" />
              <span className="text-sm font-medium tracking-widest animate-pulse uppercase">{status}</span>
            </div>
          )}
        </div>

        <div className="mt-6 flex items-center gap-6 text-white/40">
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-[18px]">aspect_ratio</span>
            <span className="text-[11px] font-medium tracking-wider uppercase">16:9 Cinema Canvas</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-[18px]">auto_fix_high</span>
            <span className="text-[11px] font-medium tracking-wider uppercase">AI Generated Assets</span>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2 mb-1">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] uppercase">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const FieldDropdown: React.FC<{
  label: string; value: string; options: string[];
  onChange: (val: string) => void; className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const listener = (e: MouseEvent) => {
      if (!ref.current || ref.current.contains(e.target as Node)) return;
      setIsOpen(false);
    };
    document.addEventListener('mousedown', listener);
    return () => document.removeEventListener('mousedown', listener);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-top">
          <div className="max-h-40 overflow-y-auto">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const DragNumberField: React.FC<{
  label: string; value: number; min?: number; max?: number;
  step?: number; suffix?: string; onChange: (val: number) => void; className?: string;
}> = ({ label, value, min = 0, max = 999, step = 1, suffix = '', onChange, className = '' }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(String(value));
  const inputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startY: number; startVal: number; moved: boolean } | null>(null);

  const commitEdit = (raw: string) => {
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) onChange(Math.min(max, Math.max(min, Math.round(parsed / step) * step)));
    setIsEditing(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isEditing) return;
    e.preventDefault();
    dragRef.current = { startY: e.clientY, startVal: value, moved: false };
    const handleMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      if (Math.abs(ev.clientY - dragRef.current.startY) > 3) dragRef.current.moved = true;
      if (dragRef.current.moved) {
        const delta = dragRef.current.startY - ev.clientY;
        const newVal = Math.round((dragRef.current.startVal + delta * step / 5) / step) * step;
        onChange(Math.min(max, Math.max(min, newVal)));
      }
    };
    const handleMouseUp = () => {
      const wasDrag = dragRef.current?.moved;
      dragRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      if (!wasDrag) {
        setEditValue(String(value));
        setIsEditing(true);
        setTimeout(() => inputRef.current?.select(), 0);
      }
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div className={`border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none transition-colors ${isEditing ? '' : 'cursor-ns-resize'} ${className}`}
      onMouseDown={handleMouseDown}>
      <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
      <div className="flex items-center justify-between">
        {isEditing ? (
          <input ref={inputRef} type="text" value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') commitEdit(editValue); if (e.key === 'Escape') setIsEditing(false); }}
            onBlur={() => commitEdit(editValue)}
            className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 m-0" autoFocus />
        ) : (
          <>
            <span className="text-[11px] font-medium text-white tracking-[0.1px] cursor-text">{value}{suffix}</span>
            <div className="flex flex-col items-center mr-1.5 -gap-px text-white/40">
              <span className="material-symbols-outlined text-[10px]">expand_less</span>
              <span className="material-symbols-outlined text-[10px] -mt-1">expand_more</span>
            </div>
          </>
        )}
      </div>
    </div>
  );
};
